    )
    case rain(intensity: Intensity, freezing: Bool
    )
    case snow(intensity: Intensity
    )
    case snowGrains
    case rainShowers(intensity: Intensity
    )
    case snowShowers(intensity: Intensity
    )
    /**
     * `hail` is `None` for a thunderstorm without hail.
     */
